def dump_hex_memory_buffer(addr, hex_byte_str):
    packet = Packet(hex_byte_str)
    idx = 0
    ascii = ""
    uval = packet.get_hex_uint8()
    while uval is not None:
        if (idx % 16) == 0:
            if ascii:
                print("  ", ascii)
                ascii = ""
            print("0x%x:" % (addr + idx), end=" ")
        print("%2.2x" % (uval), end=" ")
        if 0x20 <= uval and uval < 0x7F:
            ascii += "%c" % uval
        else:
            ascii += "."
